import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </SkeletonProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);

import { Icon } from "@/registry/erbium/ui/icon";
import { useId, useState } from "react";
import { Checkbox } from "@/registry/erbium/ui/checkbox";
import {
  Item,
  ItemActions,
  ItemContent,
  ItemGroup,
  ItemMedia,
  ItemTitle,
} from "@/registry/erbium/ui/item";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";

const projects = [
  { color: "text-tag-orange", icon: "cloud", id: "gateway", issues: 30, name: "Cloud gateway" },
  { color: "text-tag-blue", icon: "cube", id: "reader", issues: 13, name: "Read platform" },
  {
    color: "text-tag-red",
    icon: "book-open-01",
    id: "knowledge",
    issues: 9,
    name: "Knowledge hub",
  },
  {
    color: "text-tag-purple",
    icon: "link-01",
    id: "integrations",
    issues: 27,
    name: "Integrations",
  },
  {
    color: "text-tag-magenta",
    icon: "dashboard-square-01",
    id: "admin",
    issues: 27,
    name: "Admin panel",
  },
  { color: "text-tag-cyan", icon: "database-01", id: "data", issues: 29, name: "Data layer" },
  {
    color: "text-tag-green",
    icon: "magic-wand-01",
    id: "generate",
    issues: 15,
    name: "Generate",
  },
  { color: "text-tag-blue", icon: "globe-02", id: "website", issues: 15, name: "Website" },
] as const;

const ItemJoinedSelection = () => {
  const [selected, setSelected] = useState<string[]>([
    "gateway",
    "reader",
    "integrations",
    "admin",
    "generate",
    "website",
  ]);

  const idPrefix = useId();

  return (
    <section className="w-[min(48rem,92vw)]" aria-label="Projects">
      <div className="flex justify-between px-3 pb-2 text-metadata text-muted-foreground">
        <span>Name</span>
        <span>Issues</span>
      </div>
      <ItemGroup>
        {projects.map((project) => {
          const checkboxId = `${idPrefix}-${project.id}`;

          return (
            <Item
              render={<Field orientation="horizontal" />}
              key={project.id}
              role="listitem"
              size="sm"
              data-selected={selected.includes(project.id)}
              className="min-h-12"
            >
              <Checkbox
                id={checkboxId}
                checked={selected.includes(project.id)}
                aria-label={`Select ${project.name}`}
                onCheckedChange={(checked) => {
                  setSelected((current) =>
                    checked
                      ? [...current, project.id]
                      : current.filter((selectedId) => selectedId !== project.id),
                  );
                }}
              />
              <ItemMedia variant="icon">
                <span className={project.color}>
                  <Icon name={project.icon} className="size-4" aria-hidden="true" />
                </span>
              </ItemMedia>
              <ItemContent>
                <ItemTitle>
                  <FieldLabel htmlFor={checkboxId} className="cursor-pointer">
                    {project.name}
                  </FieldLabel>
                </ItemTitle>
              </ItemContent>
              <ItemActions>
                <span className="tabular-nums text-muted-foreground">{project.issues}</span>
              </ItemActions>
            </Item>
          );
        })}
      </ItemGroup>
    </section>
  );
};

export default ItemJoinedSelection;

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/use-drag-select-demo\";\n\nconst Example = () => <Demo />;\n\nexport default Example;\n";

const meta = {
  parameters: {
    docs: { description: { component: "## Usage\n\nSelects or clears neighboring items with a pointer drag. The example uses joined selection items with checkbox and keyboard support.\n\nImport `useDragSelect` from `@/registry/erbium/hooks/use-drag-select`. Supply `resolve` and `selectRange` callbacks and spread its handlers on the containing element." } },
    layout: "centered",
  },
} satisfies Meta;

export default { ...meta, title: "Hooks/Use Drag Select",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

import Demo from "../examples/use-drag-select-demo";

const Example = () => <Demo />;

export default Example;
